    "setId": "rosen-ch2-exercise-set-2-1",
    "section": "2.1",
    "number": 50,
    "difficulty": "challenging",
    "stars": 1,
    "rawText": "∗50. This exercise presents Russell’s paradox.L e t S be the\nset that contains a set x if the set x does not belong to\nitself, so that S ={ x ∣x ∉x}.\na) Show the assumption that S is a member of S leads to\nLinks a contradiction.\nb) Show the assumption thatS is not a member ofS leads\nto a contradiction.\nBy parts (a) and (b) it follows that the setS cannot be de-\nﬁned as it was. This paradox can be avoided by restricting\nthe types of elements that sets can have.",
    "prompt": "∗50. This exercise presents Russell’s paradox.L e t S be the set that contains a set x if the set x does not belong to itself, so that S ={ x ∣x ∉x}. a) Show the assumption that S is a member of S leads to Links a contradiction. b) Show the assumption thatS is not a member ofS leads to a contradiction. By parts (a) and (b) it follows that the setS cannot be defined as it was. This paradox can be avoided by restricting the types of elements that sets can have.",
