    "rawText": "72. Prove that each of the properties in parts (a)–(d) holds\nwhenever A and B are ﬁnite sets.\na) J(A, A) = 1a n ddJ(A, A) = 0\nb) J(A, B) = J(B, A)a n ddJ(A, B) = dJ(B, A)\nc) J(A, B) = 1a n ddJ(A, B) = 0 if and only if A = B\nd) 0 ≤ J(A, B) ≤ 1a n d0 ≤ dJ(A, B) ≤ 1\n∗∗ e) Show that if A, B,a n d C are sets, then dJ(A, C) ≤\ndJ(A, B)+ dJ(B, C). (This inequality is known as the\ntriangle inequality and together with parts (a), (b),\nand (c) implies that dJ is a metric.)",
