    "difficulty": "challenging",
    "stars": 1,
    "rawText": "∗ 40. Show that if S is a set, then there does not exist an onto\nfunction f from S to (S), the power set of S. Con-\nclude that |S| < |(S)|. This result is known asCantor’s\ntheorem.[ Hint: Suppose such a function f existed. Let\nT ={ s ∈S ∣s ∉f (s)} and show that no elements can ex-\nist for which f (s) = T.]",
    "prompt": "∗ 40. Show that if S is a set, then there does not exist an onto function f from S to (S), the power set of S. Conclude that |S| < |(S)|. This result is known asCantor’s theorem.[ Hint: Suppose such a function f existed. Let T ={ s ∈S ∣s ∉f (s)} and show that no elements can exist for which f (s) = T.]",
