    "number": 41,
    "difficulty": "challenging",
    "stars": 1,
    "rawText": "∗ 41. In this exercise, we prove the Schr ¨oder-Bernstein theo-\nrem. Suppose that A and B are sets where |A| ≤ |B| and\n|B| ≤ |A|. This means that there are injections f : A → B\nand g : B → A. To prove the theorem, we must show that\nthere is a bijection h : A → B,i m p l y i n gt h a t|A| = |B|.\nTo build h, we construct the chain of an el-\nement a ∈A. This chain contains the elements\na, f(a),g ( f (a)),f (g( f (a))),g ( f (g( f (a)))),… .I ta l s om a y\ncontain more elements that precede a, extending the\nchain backwards. So, if there is a b ∈B with g(b) = a,\nthen b will be the term of the chain just beforea. Because\ng may not be a surjection, there may not be any suchb,s o\nthat a is the ﬁrst element of the chain. If such a b exists,\nbecause g is an injection, it is the unique element of B\nmapped by g to a;w ed e n o t ei tb yg−1(a). (Note that this\ndeﬁnes g−1as a partial function from B to A.) We extend\nthe chain backwards as long as possible in the same way,\nadding f\n−1(g−1(a)), g−1( f−1(g−1(a))),…. To construct\nthe proof, complete these ﬁve parts.\na) Show that every element in A or in B belongs to ex-\nactly one chain.\nb) Show that there are four types of chains: chains that\nform a loop, that is, carrying them forward from ev-\nery element in the chain will eventually return to this\nelement (type 1), chains that go backwards without\nstopping (type 2), chains that go backwards and end\nin the set A (type 3), and chains that go backwards\nand end in the set B (type 4).\nc) We now deﬁne a function h : A → B.W es e th(a) =\nf (a)w h e nabelongs to a chain of type 1, 2, or 3. Show\nthat we can deﬁne h(a)w h e na is in a chain of type 4,\nby taking h(a) = g\n−1(a). In parts (d) and (e), we show\nthat this function is a bijection from A to B, proving\nthe theorem.\nd) Show that h is one-to-one. (You can consider chains\nof types 1, 2, and 3 together, but chains of type 4\nseparately.)\ne) Show that h is onto. (You need to consider chains\nof types 1, 2, and 3 together, but chains of type 4\nseparately.)",
    "prompt": "∗ 41. In this exercise, we prove the Schr ¨oder-Bernstein theorem. Suppose that A and B are sets where |A| ≤ |B| and |B| ≤ |A|. This means that there are injections f : A → B and g : B → A. To prove the theorem, we must show that there is a bijection h : A → B,i m p l y i n gt h a t|A| = |B|. To build h, we construct the chain of an element a ∈A. This chain contains the elements a, f(a),g ( f (a)),f (g( f (a))),g ( f (g( f (a)))),… .I ta l s om a y contain more elements that precede a, extending the chain backwards. So, if there is a b ∈B with g(b) = a, then b will be the term of the chain just beforea. Because g may not be a surjection, there may not be any suchb,s o that a is the first element of the chain. If such a b exists, because g is an injection, it is the unique element of B mapped by g to a;w ed e n o t ei tb yg−1(a). (Note that this defines g−1as a partial function from B to A.) We extend the chain backwards as long as possible in the same way, adding f −1(g−1(a)), g−1( f−1(g−1(a))),…. To construct the proof, complete these five parts. a) Show that every element in A or in B belongs to exactly one chain. b) Show that there are four types of chains: chains that form a loop, that is, carrying them forward from every element in the chain will eventually return to this element (type 1), chains that go backwards without stopping (type 2), chains that go backwards and end in the set A (type 3), and chains that go backwards and end in the set B (type 4). c) We now define a function h : A → B.W es e th(a) = f (a)w h e nabelongs to a chain of type 1, 2, or 3. Show that we can define h(a)w h e na is in a chain of type 4, by taking h(a) = g −1(a). In parts (d) and (e), we show that this function is a bijection from A to B, proving the theorem. d) Show that h is one-to-one. (You can consider chains of types 1, 2, and 3 together, but chains of type 4 separately.) e) Show that h is onto. (You need to consider chains of types 1, 2, and 3 together, but chains of type 4 separately.)",
