    "rawText": "13. Let f and g be functions from {1, 2, 3, 4} to {a, b, c, d}\nand from {a, b, c, d} to {1, 2, 3, 4}, respectively, with\nf (1) = d, f (2) = c, f (3) = a,a n df (4) = b,a n dg(a) = 2,\ng(b) = 1, g(c) = 3, and g(d) = 2.\na) Is f one-to-one? Is g one-to-one?\nb) Is f onto? Is g onto?\nc) Does either f or g have an inverse? If so, ﬁnd this in-\nverse.\n198 2 / Basic Structures: Sets, Functions, Sequences, Sums, and Matrices",
    "prompt": "13. Let f and g be functions from {1, 2, 3, 4} to {a, b, c, d} and from {a, b, c, d} to {1, 2, 3, 4}, respectively, with f (1) = d, f (2) = c, f (3) = a,a n df (4) = b,a n dg(a) = 2, g(b) = 1, g(c) = 3, and g(d) = 2. a) Is f one-to-one? Is g one-to-one? b) Is f onto? Is g onto? c) Does either f or g have an inverse? If so, find this inverse.",
