    "section": null,
    "number": 16,
    "difficulty": "challenging",
    "stars": 1,
    "rawText": "∗16. Suppose that f is a function from the set A to the set B.\nProve that\na) if f is one-to-one, then Sf is a one-to-one function\nfrom (A)t o (B).\nb) if f is onto function, then Sf is an onto function from\n(A)t o (B).\nc) if f is onto function, thenSf−1 is a one-to-one function\nfrom (B)t o (A).\nd) if f is one-to-one, then Sf−1 is an onto function from\n(B)t o (A).\ne) if f is a one-to-one correspondence, then Sf is a one-\nto-one correspondence from (A)t o (B)a n d Sf−1\nis a one-to-one correspondence from (B)t o (A).\n[Hint: Use parts (a)–(d).]",
    "prompt": "∗16. Suppose that f is a function from the set A to the set B. Prove that a) if f is one-to-one, then Sf is a one-to-one function from (A)t o (B). b) if f is onto function, then Sf is an onto function from (A)t o (B). c) if f is onto function, thenSf−1 is a one-to-one function from (B)t o (A). d) if f is one-to-one, then Sf−1 is an onto function from (B)t o (A). e) if f is a one-to-one correspondence, then Sf is a oneto-one correspondence from (A)t o (B)a n d Sf−1 is a one-to-one correspondence from (B)t o (A). [Hint: Use parts (a)–(d).]",
